using System;
using System.Collections.Generic;
using System.IO;
using System.Linq;
using System.Net.Sockets;
using System.Text;
using System.Threading.Tasks;

var Globals = new TCAdmin.Scripting.Engines.Addons.CSharpGameGlobals(); // DO NOT MODIFY THIS LINE

// The Isle: Evrima RCON (TCP, not Source RCON). Login = 0x01 + password + 0x00, answered "Password Accepted";
// a command = 0x02 + one opcode byte + its arguments + 0x00. Type "help" for the command list.
var opcodes = new Dictionary<string, byte>(StringComparer.OrdinalIgnoreCase)
{
    ["announce"] = 0x10, ["directmessage"] = 0x11, ["serverdetails"] = 0x12, ["wipecorpses"] = 0x13,
    ["getplayables"] = 0x14, ["updateplayables"] = 0x15, ["togglemigrations"] = 0x19, ["ban"] = 0x20,
    ["togglegrowthmultiplier"] = 0x21, ["setgrowthmultiplier"] = 0x22, ["togglenetupdatedistancechecks"] = 0x23,
    ["kick"] = 0x30, ["playerlist"] = 0x40, ["save"] = 0x50, ["pause"] = 0x60, ["custom"] = 0x70,
    ["getplayerdata"] = 0x77, ["togglewhitelist"] = 0x81, ["addwhitelist"] = 0x82, ["removewhitelist"] = 0x83,
    ["toggleglobalchat"] = 0x84, ["togglehumans"] = 0x86, ["toggleai"] = 0x90, ["disableaiclasses"] = 0x91,
    ["aidensity"] = 0x92, ["getqueuestatus"] = 0x93, ["toggleailearning"] = 0x94,
};

async Task<string> ReadReply(NetworkStream stream, TcpClient client, int quietMs, int maxMs)
{
    var buffer = new byte[16384];
    var output = new MemoryStream();
    var hardEnd = DateTime.UtcNow.AddMilliseconds(maxMs);
    var lastData = DateTime.UtcNow;
    while (DateTime.UtcNow < hardEnd && (output.Length == 0 || DateTime.UtcNow - lastData < TimeSpan.FromMilliseconds(quietMs)))
    {
        if (stream.DataAvailable)
        {
            var n = stream.Read(buffer, 0, buffer.Length);
            if (n <= 0) break;
            output.Write(buffer, 0, n);
            lastData = DateTime.UtcNow;
        }
        else
        {
            if (client.Client.Poll(0, SelectMode.SelectRead) && client.Client.Available == 0) break; // closed by the server
            await Task.Delay(50);
        }
    }
    return Encoding.UTF8.GetString(output.ToArray()).Replace("\0", "").Trim();
}

var result = "";
try
{
    var line = (Globals.Variables.Parse<string>("Command") ?? "").Trim();
    var space = line.IndexOf(' ');
    var name = space < 0 ? line : line.Substring(0, space);
    var arguments = space < 0 ? "" : line.Substring(space + 1).Trim();

    if (name.Length == 0 || name.Equals("help", StringComparison.OrdinalIgnoreCase))
    {
        result = "Evrima RCON commands: " + string.Join(", ", opcodes.Keys.OrderBy(k => k)) +
                 "\nExamples: announce Hello everyone | playerlist | save | kick <SteamID>,<reason> | ban <name>,<SteamID>,<reason>,<minutes>";
    }
    else if (!opcodes.TryGetValue(name, out var opcode))
    {
        result = "Unknown command '" + name + "'. Type help for the list.";
    }
    else
    {
        var address = Globals.Variables.Parse<string>("Address");
        var port = Globals.Variables.Parse<int>("Port");
        var password = Globals.Variables.Parse<string>("Password") ?? "";

        using var client = new TcpClient();
        var connect = client.ConnectAsync(address, port);
        if (await Task.WhenAny(connect, Task.Delay(5000)) != connect)
            throw new Exception("timed out connecting to " + address + ":" + port);
        await connect;
        var stream = client.GetStream();

        var login = new List<byte> { 0x01 };
        login.AddRange(Encoding.UTF8.GetBytes(password));
        login.Add(0x00);
        await stream.WriteAsync(login.ToArray(), 0, login.Count);
        var auth = await ReadReply(stream, client, 300, 5000);
        if (auth.IndexOf("Accepted", StringComparison.OrdinalIgnoreCase) < 0)
            throw new Exception("login refused (" + (auth.Length == 0 ? "no reply" : auth) + ")");

        var packet = new List<byte> { 0x02, opcode };
        packet.AddRange(Encoding.UTF8.GetBytes(arguments));
        packet.Add(0x00);
        await stream.WriteAsync(packet.ToArray(), 0, packet.Count);
        result = await ReadReply(stream, client, 750, 8000);
        if (result.Length == 0) result = name + " sent.";
    }
}
catch (Exception ex)
{
    result = "Evrima RCON error: " + ex.Message;
}
Globals.ReturnValue = result;

//refAssemblies: System.Diagnostics.Process.dll
using System;
using System.Collections.Generic;
using System.Diagnostics;
using System.IO;
using System.Linq;
using System.Threading.Tasks;

var Globals = new TCAdmin.Scripting.Engines.Addons.CSharpGameGlobals(); // DO NOT MODIFY THIS LINE

// Graceful stop for The Isle (Linux): SIGINT makes the server save and exit ("LogExit: Exiting."), like Ctrl+C.
// The ^c stop command does not reach it through the terminal, so signal the server binary of THIS service directly.
var root = ((string)ThisService.RootDirectory).TrimEnd('/');
const int maxWaitSeconds = 120;

List<int> ServerPids()
{
    var pids = new List<int>();
    foreach (var dir in Directory.EnumerateDirectories("/proc"))
    {
        if (!int.TryParse(Path.GetFileName(dir), out var pid)) continue;
        try
        {
            var exe = new FileInfo(Path.Combine(dir, "exe")).LinkTarget ?? "";
            if (exe.StartsWith(root + "/") && exe.EndsWith("TheIsleServer-Linux-Shipping")) pids.Add(pid);
        }
        catch { } // processes of other users, or gone meanwhile
    }
    return pids;
}

var targets = ServerPids();
if (targets.Count == 0)
{
    ScriptConsole.WriteLine((object)"The server is not running; nothing to save.");
    return;
}

foreach (var pid in targets)
{
    using (var kill = Process.Start(new ProcessStartInfo("kill", "-INT " + pid) { UseShellExecute = false, RedirectStandardError = true }))
    {
        kill.WaitForExit();
        if (kill.ExitCode != 0) ScriptConsole.WriteLine((object)("Could not signal process " + pid + ": " + kill.StandardError.ReadToEnd().Trim()));
    }
}
ScriptConsole.WriteLine((object)("Sent SIGINT to " + string.Join(", ", targets) + "; waiting for the server to save and exit."));

for (var second = 1; second <= maxWaitSeconds; second++)
{
    await Task.Delay(1000, ThisCancellationToken);
    if (ServerPids().Count == 0)
    {
        ScriptConsole.WriteLine((object)("The server saved and exited after " + second + " s."));
        return;
    }
}
ScriptConsole.WriteLine((object)("The server did not exit within " + maxWaitSeconds + " s; the panel stops it now."));
